package scheduler

import (
	"context"
	"sync"
	"sync/atomic"
	"time"
)

// Job defines a unit of work.
type Job struct {
	ID         string
	Fn         func(ctx context.Context) error
	MaxRetries int           // 0 = no retry
	Delay      time.Duration // initial delay before first run
}

// JobResult records the outcome of a job run.
type JobResult struct {
	JobID    string
	Attempts int
	Err      error
}

// Metrics tracks scheduler statistics.
type Metrics struct {
	Succeeded atomic.Int64
	Failed    atomic.Int64
	Retried   atomic.Int64
}

// Scheduler runs jobs concurrently with retry and metrics.
type Scheduler struct {
	ctx       context.Context
	cancel    context.CancelFunc
	wg        sync.WaitGroup
	workers   int
	jobs      chan Job
	results   chan JobResult
	metrics   Metrics
}

// New creates a scheduler with n worker goroutines.
func New(ctx context.Context, workers int) *Scheduler {
	ctx2, cancel := context.WithCancel(ctx)
	return &Scheduler{
		ctx:     ctx2,
		cancel:  cancel,
		workers: workers,
		jobs:    make(chan Job, 64),
		results: make(chan JobResult, 64),
	}
}

// Start launches worker goroutines.
func (s *Scheduler) Start() {
	// TODO
}

// Submit adds a job to the queue.
func (s *Scheduler) Submit(job Job) {
	s.jobs <- job
}

// Stop signals all workers to finish and waits.
func (s *Scheduler) Stop() {
	s.cancel()
	close(s.jobs)
	s.wg.Wait()
	close(s.results)
}

// Results returns the results channel.
func (s *Scheduler) Results() <-chan JobResult {
	return s.results
}

// GetMetrics returns a copy of current metrics.
func (s *Scheduler) GetMetrics() (succeeded, failed, retried int64) {
	return s.metrics.Succeeded.Load(), s.metrics.Failed.Load(), s.metrics.Retried.Load()
}

