package scheduler_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/ai-verification/job-scheduler/scheduler"
)

func TestSuccessfulJob(t *testing.T) {
	s := scheduler.New(context.Background(), 2)
	s.Start()
	called := make(chan struct{}, 1)
	s.Submit(scheduler.Job{
		ID: "j1",
		Fn: func(ctx context.Context) error {
			called <- struct{}{}
			return nil
		},
	})
	select {
	case <-called:
	case <-time.After(time.Second):
		t.Fatal("job not called")
	}
	s.Stop()
	succeeded, _, _ := s.GetMetrics()
	if succeeded != 1 {
		t.Fatalf("expected 1 succeeded, got %d", succeeded)
	}
}

func TestJobRetry(t *testing.T) {
	s := scheduler.New(context.Background(), 1)
	s.Start()
	attempts := 0
	s.Submit(scheduler.Job{
		ID:         "retry",
		MaxRetries: 2,
		Fn: func(ctx context.Context) error {
			attempts++
			if attempts < 3 {
				return errors.New("not yet")
			}
			return nil
		},
	})
	s.Stop()
	for range s.Results() {} // drain
	if attempts != 3 {
		t.Fatalf("expected 3 attempts, got %d", attempts)
	}
	_, _, retried := s.GetMetrics()
	if retried != 2 {
		t.Fatalf("expected 2 retries, got %d", retried)
	}
}

func TestJobFailsAfterMaxRetries(t *testing.T) {
	s := scheduler.New(context.Background(), 1)
	s.Start()
	s.Submit(scheduler.Job{
		ID:         "fail",
		MaxRetries: 1,
		Fn: func(ctx context.Context) error { return errors.New("always") },
	})
	s.Stop()
	var results []scheduler.JobResult
	for r := range s.Results() {
		results = append(results, r)
	}
	if len(results) != 1 || results[0].Err == nil {
		t.Fatal("expected failed result")
	}
	_, failed, _ := s.GetMetrics()
	if failed != 1 {
		t.Fatalf("expected 1 failed, got %d", failed)
	}
}
